insert into clients (id, name, goal, notes) values ('d37a7e3c-9838-59d4-9f5a-b86457bc901c', '👨 Men''s 12wk Templates', 'Program templates', 'Age-banded men''s programs (30-40 / 41-55 / 56-70 x Beginner-Moderate-Advanced). Duplicate to a client, then adjust.') on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('8944cd3e-649d-5404-ae55-c5d463b224e0', 'd37a7e3c-9838-59d4-9f5a-b86457bc901c', 'Men 30-40 · Beginner (12wk)', 'Strength', 'Beginner', 12, '{"1": "Build movement skill, strength, muscle, and aerobic base while protecting recovery from work and sleep stress. Schedule: Alternate A\u2013B\u2013A, then B\u2013A\u2013B (3 days/week).", "4": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "8": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "12": "Consolidation \u2014 reduce volume 30-40%, keep quality. Optional submax field test."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('4ce58e2d-2f3a-54c3-8d0e-82dad7f10492', 'd37a7e3c-9838-59d4-9f5a-b86457bc901c', 'Men 30-40 · Moderate (12wk)', 'Strength', 'Intermediate', 12, '{"1": "Build strength and hypertrophy with sufficient aerobic work and controlled high-intensity exposure. Schedule: Mon A \u2022 Tue B \u2022 Thu C \u2022 Sat D (4 days/week).", "4": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "8": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "12": "Consolidation \u2014 reduce volume 30-40%, keep quality. Optional submax field test."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('93535cad-bef2-5671-a01d-9f96b742a5ad', 'd37a7e3c-9838-59d4-9f5a-b86457bc901c', 'Men 30-40 · Advanced (12wk)', 'Strength', 'Advanced', 12, '{"1": "Develop maximal strength and power without sacrificing aerobic capacity; power stops before speed loss. Schedule: Mon lower power \u2022 Tue upper power \u2022 Thu strength \u2022 Sat hypertrophy (4 days/week).", "4": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "8": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "12": "Consolidation \u2014 reduce volume 30-40%, keep quality. Optional submax field test."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('4cee649c-6d7f-54f5-9b77-978fad8e8d1e', 'd37a7e3c-9838-59d4-9f5a-b86457bc901c', 'Men 41-55 · Beginner (12wk)', 'Strength', 'Beginner', 12, '{"1": "Preserve/build muscle and aerobic fitness while using more deliberate tendon loading and recovery. Rest 2\u20133 min after squats/deadlifts; use 2\u20133 sec lowering on accessories. Schedule: Alternate A\u2013B\u2013A, then B\u2013A\u2013B (3 days/week).", "4": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "8": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "12": "Consolidation \u2014 reduce volume 30-40%, keep quality. Optional submax field test."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('11781edd-c609-5759-8f81-9a5247cc90b8', 'd37a7e3c-9838-59d4-9f5a-b86457bc901c', 'Men 41-55 · Moderate (12wk)', 'Strength', 'Intermediate', 12, '{"1": "Preserve strength, muscle, tendon capacity, and metabolic health with 48 hours between demanding full-body sessions. Schedule: Mon A \u2022 Wed B \u2022 Fri C (3 days/week).", "4": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "8": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "12": "Consolidation \u2014 reduce volume 30-40%, keep quality. Optional submax field test."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('9e876f4f-8ebd-5282-b73f-56e48349f724', 'd37a7e3c-9838-59d4-9f5a-b86457bc901c', 'Men 41-55 · Advanced (12wk)', 'Strength', 'Advanced', 12, '{"1": "Use high/low stress distribution to maintain strength and power while managing joint, tendon, and systemic recovery. Schedule: Mon lower power/strength \u2022 Tue upper power/strength \u2022 Thu full-body strength \u2022 Sat hypertrophy (4 days/week).", "4": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "8": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "12": "Consolidation \u2014 reduce volume 30-40%, keep quality. Optional submax field test."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('33268075-a299-5583-98e8-5b1cca511ab9', 'd37a7e3c-9838-59d4-9f5a-b86457bc901c', 'Men 56-70 · Beginner (12wk)', 'Strength', 'Beginner', 12, '{"1": "Prevent sarcopenia, preserve function and balance, and build cardiovascular capacity. Use supported variations as required. Schedule: Alternate A\u2013B\u2013A, then B\u2013A\u2013B; add balance 2\u20133\u00d7 weekly (3 days/week).", "4": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "8": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "12": "Consolidation \u2014 reduce volume 30-40%, keep quality. Optional submax field test."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('25037e0e-8d9f-58c6-8297-8c0091f8d41e', 'd37a7e3c-9838-59d4-9f5a-b86457bc901c', 'Men 56-70 · Moderate (12wk)', 'Strength', 'Intermediate', 12, '{"1": "Maintain muscle, bone loading, balance, fast-force capacity, and independence without using age as a reason for ineffective light loading. Schedule: Mon strength \u2022 Wed hypertrophy \u2022 Fri power/strength (3 days/week).", "4": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "8": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "12": "Consolidation \u2014 reduce volume 30-40%, keep quality. Optional submax field test."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('92078d94-7dde-579d-acd0-2f788c9e8a95', 'd37a7e3c-9838-59d4-9f5a-b86457bc901c', 'Men 56-70 · Advanced (12wk)', 'Strength', 'Advanced', 12, '{"1": "Preserve high-level strength and power with three high-quality sessions; a fourth day is recovery/technique only when justified. Schedule: Mon power/strength \u2022 Wed hypertrophy \u2022 Fri power/strength (3 days/week).", "4": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "8": "Deload \u2014 drop a set per exercise and ~20% load. Cardio: Zone 2 or recovery only.", "12": "Consolidation \u2014 reduce volume 30-40%, keep quality. Optional submax field test."}'::jsonb) on conflict (id) do nothing;
